const AUTO_TITLE_PATTERN =
  /^Untitled Node - \d{4}-\d{2}-\d{2}-\d{2}:\d{2}:\d{2}$/;

/** True when the stored title was system-generated (legacy) or blank. */
export function isAutoGeneratedTitle(title: string | null | undefined): boolean {
  const trimmed = title?.trim() ?? "";
  if (!trimmed) return true;
  if (AUTO_TITLE_PATTERN.test(trimmed)) return true;
  if (trimmed.toLowerCase() === "untitled note") return true;
  return false;
}

/** Real user-set title only — never an auto-generated or empty placeholder. */
export function realTitle(title: string | null | undefined): string | null {
  if (isAutoGeneratedTitle(title)) return null;
  return title!.trim();
}
